/* 2-axis analog joystick with wire-break detection (PUC-1720) */
#ifndef PUC_JOYSTICK_H
#define PUC_JOYSTICK_H

#include <stdbool.h>
#include <stdint.h>

typedef struct {
    int16_t x;   /* [-DRIVE_MAX_CMD, DRIVE_MAX_CMD], deadband applied */
    int16_t y;
} joy_sample_t;

void joystick_init(void);

/* false when either axis is outside the valid electrical window
 * (broken wire, short) - caller must treat as neutral. */
bool joystick_read(joy_sample_t *out);

#endif

/* Battery voltage sense + I2C meter (PUC-1720) */
#ifndef PUC_BATTERY_H
#define PUC_BATTERY_H

#include <stdint.h>

void battery_init(void);
void battery_poll(void);

/* Pack voltage from the resistor divider, filtered. */
float battery_voltage(void);

/* Speed ceiling in Sabertooth counts: DRIVE_MAX_CMD when healthy,
 * ramping down between VBATT_LOW_DERATE and VBATT_LOW_CUTOFF (PWR-01). */
int32_t battery_speed_limit(void);

#endif

/* Dual-channel E-stop monitor + contactor enable (PUC-1720) */
#ifndef PUC_ESTOP_H
#define PUC_ESTOP_H

#include <stdbool.h>

typedef enum {
    ESTOP_RUN = 0,          /* both channels closed, contactor enabled   */
    ESTOP_STOPPED,          /* chain open: neutral + contactor released  */
    ESTOP_FAULT_DISCREPANCY /* channels disagree > limit: latched fault  */
} estop_state_t;

void estop_init(void);
void estop_poll(void);
bool estop_drive_permitted(void);
estop_state_t estop_state(void);

#endif

/* E-stop: two opto-isolated inputs watch the two contacts of the E-stop
 * chain (PC817 pull the GPIO low while the chain is CLOSED and powered).
 * Firmware releases the contactor enable within ESTOP_REACTION_MS of
 * either channel opening; the hardwired chain opens the SW80 coil circuit
 * independently of this code (the MOSFET is in SERIES with the chain).
 *
 * A discrepancy (one channel open, the other closed, for longer than
 * ESTOP_DISCREPANCY_MS) means a welded contact or broken wire: latch a
 * fault that only a power cycle clears (TC-000003 step 3).
 */
#include "pico/stdlib.h"
#include "config.h"
#include "estop.h"

static estop_state_t state = ESTOP_STOPPED;
static absolute_time_t discrepancy_since;
static bool discrepancy_timing = false;

void estop_init(void)
{
    gpio_init(PIN_ESTOP_CH1);
    gpio_set_dir(PIN_ESTOP_CH1, GPIO_IN);
    gpio_pull_up(PIN_ESTOP_CH1);
    gpio_init(PIN_ESTOP_CH2);
    gpio_set_dir(PIN_ESTOP_CH2, GPIO_IN);
    gpio_pull_up(PIN_ESTOP_CH2);

    gpio_init(PIN_CONTACTOR_EN);
    gpio_set_dir(PIN_CONTACTOR_EN, GPIO_OUT);
    gpio_put(PIN_CONTACTOR_EN, 0);          /* start released */
}

void estop_poll(void)
{
    if (state == ESTOP_FAULT_DISCREPANCY)
        return;                              /* latched until power cycle */

    /* opto ON pulls the pin LOW -> low = channel closed = safe to run */
    bool ch1_closed = !gpio_get(PIN_ESTOP_CH1);
    bool ch2_closed = !gpio_get(PIN_ESTOP_CH2);

    if (ch1_closed != ch2_closed) {
        if (!discrepancy_timing) {
            discrepancy_timing = true;
            discrepancy_since = get_absolute_time();
        } else if (absolute_time_diff_us(discrepancy_since, get_absolute_time())
                   > (int64_t)ESTOP_DISCREPANCY_MS * 1000) {
            state = ESTOP_FAULT_DISCREPANCY;
            gpio_put(PIN_CONTACTOR_EN, 0);
            return;
        }
    } else {
        discrepancy_timing = false;
    }

    if (ch1_closed && ch2_closed) {
        state = ESTOP_RUN;
        gpio_put(PIN_CONTACTOR_EN, 1);
    } else {
        state = ESTOP_STOPPED;
        gpio_put(PIN_CONTACTOR_EN, 0);
    }
}

bool estop_drive_permitted(void) { return state == ESTOP_RUN; }
estop_state_t estop_state(void)  { return state; }

/* PUC-1720 drive interface firmware - main loop
 *
 * 100 Hz control loop:
 *   read joystick -> validate -> mix to L/R wheel commands -> ramp ->
 *   Sabertooth packet serial; E-stop chain gates the contactor enable
 *   and forces neutral; battery voltage derates top speed near empty.
 *
 * Safety notes:
 *  - The contactor (Albright SW80) is the actual power break; this MCU
 *    only *releases* it. The hardwired E-stop chain opens the coil
 *    circuit regardless of firmware state (REQ-000005 / ELEC-01).
 *  - The Sabertooth serial watchdog stops the motors if this loop dies.
 */
#include "pico/stdlib.h"
#include "hardware/watchdog.h"
#include "config.h"
#include "joystick.h"
#include "estop.h"
#include "sabertooth.h"
#include "battery.h"

static int16_t ramp(int16_t current, int16_t target)
{
    const int16_t step = (int16_t)(DRIVE_MAX_CMD * LOOP_PERIOD_MS / DRIVE_RAMP_MS);
    if (target > current + step) return current + step;
    if (target < current - step) return current - step;
    return target;
}

int main(void)
{
    stdio_init_all();
    joystick_init();
    estop_init();
    sabertooth_init();
    battery_init();

    watchdog_enable(WATCHDOG_TIMEOUT_MS, true);

    int16_t cmd_left = 0, cmd_right = 0;

    while (true) {
        watchdog_update();

        estop_poll();
        battery_poll();

        joy_sample_t joy;
        bool joy_ok = joystick_read(&joy);

        int16_t tgt_left = 0, tgt_right = 0;
        if (joy_ok && estop_drive_permitted()) {
            /* arcade mix: y = throttle, x = turn */
            int32_t l = joy.y + joy.x;
            int32_t r = joy.y - joy.x;
            int32_t limit = battery_speed_limit();   /* <= DRIVE_MAX_CMD */
            if (l >  limit) l =  limit;
            if (l < -limit) l = -limit;
            if (r >  limit) r =  limit;
            if (r < -limit) r = -limit;
            tgt_left  = (int16_t)l;
            tgt_right = (int16_t)r;
        }

        cmd_left  = ramp(cmd_left,  tgt_left);
        cmd_right = ramp(cmd_right, tgt_right);

        /* E-stop active: skip the ramp, command neutral NOW */
        if (!estop_drive_permitted()) {
            cmd_left = cmd_right = 0;
        }

        sabertooth_drive(SABER_ADDRESS, cmd_left, cmd_right);

        sleep_ms(LOOP_PERIOD_MS);
    }
}

/* Sabertooth 2x60 packet serial: addr, cmd, data, checksum((a+c+d)&0x7F).
 * Commands: 0 fwd M1, 1 rev M1, 4 fwd M2, 5 rev M2.
 * The controller's serial timeout (set by DIP wizard, SABER_TIMEOUT_MS)
 * is the backstop if this stream stops.
 */
#include "pico/stdlib.h"
#include "hardware/uart.h"
#include "config.h"
#include "sabertooth.h"

static void send_packet(uint8_t address, uint8_t command, uint8_t data)
{
    uint8_t pkt[4] = {
        address, command, data,
        (uint8_t)((address + command + data) & 0x7F)
    };
    uart_write_blocking(UART_SABER, pkt, sizeof pkt);
}

void sabertooth_init(void)
{
    uart_init(UART_SABER, SABER_BAUD);
    gpio_set_function(PIN_SABER_TX, GPIO_FUNC_UART);
    gpio_set_function(PIN_SABER_RX, GPIO_FUNC_UART);
    /* Sabertooth autobauds on 0xAA after power-up */
    uint8_t bauding = 0xAA;
    sleep_ms(2000);
    uart_write_blocking(UART_SABER, &bauding, 1);
    sabertooth_neutral(SABER_ADDRESS);
}

static void drive_channel(uint8_t address, uint8_t fwd_cmd, uint8_t rev_cmd,
                          int16_t value)
{
    if (value >  DRIVE_MAX_CMD) value =  DRIVE_MAX_CMD;
    if (value < -DRIVE_MAX_CMD) value = -DRIVE_MAX_CMD;
    if (value >= 0) send_packet(address, fwd_cmd, (uint8_t)value);
    else            send_packet(address, rev_cmd, (uint8_t)(-value));
}

void sabertooth_drive(uint8_t address, int16_t left, int16_t right)
{
    drive_channel(address, 0, 1, left);   /* M1 = left pair  */
    drive_channel(address, 4, 5, right);  /* M2 = right pair */
}

void sabertooth_neutral(uint8_t address)
{
    send_packet(address, 0, 0);
    send_packet(address, 4, 0);
}

/* Sabertooth 2x60 packet-serial driver (PUC-1720) */
#ifndef PUC_SABERTOOTH_H
#define PUC_SABERTOOTH_H

#include <stdint.h>

void sabertooth_init(void);

/* left/right in [-127, 127]; 0 = stop. Sends motor 1 + motor 2 packets. */
void sabertooth_drive(uint8_t address, int16_t left, int16_t right);

/* Explicit neutral both channels (used by the E-stop path). */
void sabertooth_neutral(uint8_t address);

#endif

#include "pico/stdlib.h"
#include "hardware/adc.h"
#include "config.h"
#include "joystick.h"

void joystick_init(void)
{
    adc_init();
    adc_gpio_init(PIN_JOY_X_ADC);
    adc_gpio_init(PIN_JOY_Y_ADC);
}

static bool read_axis(unsigned input, int16_t *out)
{
    adc_select_input(input);
    uint16_t raw = adc_read();               /* 12-bit */
    if (raw < JOY_FAULT_LO || raw > JOY_FAULT_HI)
        return false;                        /* CTL-02: fail to neutral */

    int32_t centred = (int32_t)raw - JOY_CENTRE_COUNTS;
    if (centred > -JOY_DEADBAND_COUNTS && centred < JOY_DEADBAND_COUNTS) {
        *out = 0;
        return true;
    }
    /* rescale the live range outside the deadband to full command */
    int32_t span = JOY_CENTRE_COUNTS - JOY_DEADBAND_COUNTS;
    if (centred > 0) centred -= JOY_DEADBAND_COUNTS;
    else             centred += JOY_DEADBAND_COUNTS;
    *out = (int16_t)(centred * DRIVE_MAX_CMD / span);
    return true;
}

bool joystick_read(joy_sample_t *out)
{
    int16_t x, y;
    /* ADC0 = GPIO26 = input 0, ADC1 = GPIO27 = input 1 */
    bool ok = read_axis(0, &x) && read_axis(1, &y);
    if (!ok) {
        out->x = out->y = 0;
        return false;
    }
    out->x = x;
    out->y = y;
    return true;
}

#include "pico/stdlib.h"
#include "hardware/adc.h"
#include "hardware/i2c.h"
#include "config.h"
#include "battery.h"

static float vbatt_filt = 24.0f;

void battery_init(void)
{
    adc_gpio_init(PIN_VBATT_ADC);
    i2c_init(I2C_BATT, 100 * 1000);
    gpio_set_function(PIN_BATT_SDA, GPIO_FUNC_I2C);
    gpio_set_function(PIN_BATT_SCL, GPIO_FUNC_I2C);
    gpio_pull_up(PIN_BATT_SDA);
    gpio_pull_up(PIN_BATT_SCL);
}

void battery_poll(void)
{
    adc_select_input(2);                     /* GPIO28 */
    uint16_t raw = adc_read();
    float v = (float)raw * 3.3f / 4096.0f * VBATT_DIVIDER;
    vbatt_filt += 0.05f * (v - vbatt_filt);  /* ~200 ms time constant */

    /* Smart-battery style meter on I2C: read RelativeStateOfCharge (0x0d).
     * Best effort - the divider is the safety-relevant source. */
    uint8_t reg = 0x0d, soc[2];
    if (i2c_write_timeout_us(I2C_BATT, BATT_METER_ADDR, &reg, 1, true, 2000) == 1)
        i2c_read_timeout_us(I2C_BATT, BATT_METER_ADDR, soc, 2, false, 2000);
}

float battery_voltage(void) { return vbatt_filt; }

int32_t battery_speed_limit(void)
{
    if (vbatt_filt >= VBATT_LOW_DERATE) return DRIVE_MAX_CMD;
    if (vbatt_filt <= VBATT_LOW_CUTOFF) return DRIVE_MAX_CMD / 4;
    float span = VBATT_LOW_DERATE - VBATT_LOW_CUTOFF;
    float frac = (vbatt_filt - VBATT_LOW_CUTOFF) / span;   /* 0..1 */
    int32_t lim = DRIVE_MAX_CMD / 4
                + (int32_t)(frac * (DRIVE_MAX_CMD - DRIVE_MAX_CMD / 4));
    return lim;
}
